mapper.select:
SELECT g.goods_id AS goodsId, g.user_id AS userId, g.category_id AS categoryId, g.goods_name AS goodsName, g.description AS description, g.price AS price, g.status AS status, g.view_count AS viewCount, g.favorite_count AS favoriteCount, g.condition_level AS conditionLevel, g.campus AS campus, g.location AS location, g.create_time AS createTime, gi.image_url AS imageUrl FROM goods g LEFT JOIN goods_image gi ON gi.image_id = ( SELECT image_id FROM goods_image WHERE goods_id = g.goods_id ORDER BY is_primary DESC, sort_order ASC, image_id ASC LIMIT 1 )
g.status = 1
AND g.goods_name LIKE CONCAT('%', #{goodsName}, '%')
AND g.category_id = #{categoryId}
AND g.price >= #{minPrice}
AND g.price <= #{maxPrice}
AND g.condition_level = #{conditionLevel}
AND g.campus = #{campus}
ORDER BY g.price ASC, g.goods_id DESC
ORDER BY g.price DESC, g.goods_id DESC
ORDER BY g.favorite_count DESC, g.view_count DESC, g.goods_id DESC
ORDER BY g.create_time DESC, g.goods_id DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM goods g



    g.status = 1


        AND g.goods_name LIKE CONCAT('%', #{goodsName}, '%')



        AND g.category_id = #{categoryId}



