UPDATE goods
SET favorite_count = favorite_count + 1
WHERE goods_id = #{goodsId}

UPDATE goods
SET favorite_count = GREATEST(favorite_count - 1, 0)
WHERE goods_id = #{goodsId}

mapper.select:
SELECT g.goods_id AS goodsId, g.goods_name AS goodsName, g.price AS price, g.status AS status, g.view_count AS viewCount, g.favorite_count AS favoriteCount, g.condition_level AS conditionLevel, g.campus AS campus, g.location AS location, g.create_time AS createTime, g.user_id AS userId, u.username AS sellerName, c.category_name AS categoryName FROM goods g LEFT JOIN `user` u ON g.user_id = u.user_id LEFT JOIN category c ON g.category_id = c.category_id
AND g.goods_name LIKE CONCAT('%', #{goodsName}, '%')
AND g.category_id = #{categoryId}
AND g.status = #{status}
ORDER BY g.goods_id DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM goods g




